"""SQLite SQL statements for operations snapshots, alerts, and deliveries.

These statements are SQLite-specific and do not imply PostgreSQL compatibility.
"""
HEARTBEATS = "SELECT worker_id,started_at,last_seen_at,state,metadata_json FROM generation_worker_heartbeats ORDER BY last_seen_at DESC"
OUTBOX_AGGREGATES = "SELECT status,COUNT(*) AS n,MIN(CASE WHEN status='pending' THEN available_at WHEN status='processing' THEN COALESCE(claimed_at,created_at) END) AS oldest FROM generation_outbox GROUP BY status"
POLL_AGGREGATES = "SELECT status,phase,COUNT(*) AS n,MIN(CASE WHEN status='pending' THEN available_at WHEN status='processing' THEN COALESCE(claimed_at,created_at) END) AS oldest FROM generation_poll_tasks GROUP BY status,phase"
ALERT_AGGREGATES = "SELECT status,severity,COUNT(*) AS n FROM generation_ops_alerts GROUP BY status,severity"
DELIVERY_AGGREGATES = "SELECT status,COUNT(*) AS n FROM generation_ops_alert_deliveries GROUP BY status"
ACTIVE_FINGERPRINTS = "SELECT fingerprint FROM generation_ops_alerts WHERE status='active'"
ALERT_BY_FINGERPRINT = "SELECT alert_id FROM generation_ops_alerts WHERE fingerprint=?"
UPDATE_ALERT = "UPDATE generation_ops_alerts SET severity=?,status='active',title=?,details_json=?,last_seen_at=?,resolved_at=NULL WHERE fingerprint=?"
UPSERT_DELIVERY = "INSERT INTO generation_ops_alert_deliveries(delivery_id,alert_id,destination,status,available_at,created_at) VALUES(?,?,?,'pending',?,?) ON CONFLICT(alert_id,destination) DO UPDATE SET status='pending',attempts=0,available_at=excluded.available_at,last_error=NULL,delivered_at=NULL,claimed_at=NULL,claimed_by=NULL,lease_expires_at=NULL"
INSERT_ALERT = "INSERT INTO generation_ops_alerts(alert_id,fingerprint,alert_type,severity,status,title,details_json,first_seen_at,last_seen_at) VALUES(?,?,?,?,?,?,?,?,?)"
INSERT_DELIVERY = "INSERT INTO generation_ops_alert_deliveries(delivery_id,alert_id,destination,status,available_at,created_at) VALUES(?,?,?,'pending',?,?)"
RESOLVE_ALERT = "UPDATE generation_ops_alerts SET status='resolved',resolved_at=?,last_seen_at=? WHERE fingerprint=? AND status='active'"
LIST_ALERTS = "SELECT alert_id,fingerprint,alert_type,severity,status,title,details_json,first_seen_at,last_seen_at,resolved_at FROM generation_ops_alerts WHERE status=? ORDER BY CASE severity WHEN 'critical' THEN 0 ELSE 1 END,last_seen_at DESC LIMIT ?"
REQUEUE_STALE_DELIVERY = "UPDATE generation_ops_alert_deliveries SET status='pending',claimed_at=NULL,claimed_by=NULL,lease_expires_at=NULL,available_at=? WHERE status='processing' AND lease_expires_at IS NOT NULL AND lease_expires_at<=?"
SELECT_READY_DELIVERY = "SELECT d.*,a.alert_type,a.severity,a.title,a.details_json,a.fingerprint,a.status AS alert_status FROM generation_ops_alert_deliveries d JOIN generation_ops_alerts a ON a.alert_id=d.alert_id WHERE d.status='pending' AND d.available_at<=? ORDER BY d.created_at LIMIT 1"
CLAIM_DELIVERY = "UPDATE generation_ops_alert_deliveries SET status='processing',attempts=attempts+1,claimed_at=?,claimed_by=?,lease_expires_at=? WHERE delivery_id=? AND status='pending' AND available_at<=?"
DELIVERY_ATTEMPTS = "SELECT attempts FROM generation_ops_alert_deliveries WHERE delivery_id=? AND status='processing' AND claimed_by=? AND lease_expires_at>?"
DELIVERY_MARK_SENT = "UPDATE generation_ops_alert_deliveries SET status='delivered',delivered_at=?,claimed_at=NULL,claimed_by=NULL,lease_expires_at=NULL,last_error=NULL WHERE delivery_id=? AND status='processing' AND claimed_by=? AND lease_expires_at>?"
DELIVERY_MARK_FAILED = "UPDATE generation_ops_alert_deliveries SET status='failed',claimed_at=NULL,claimed_by=NULL,lease_expires_at=NULL,last_error=? WHERE delivery_id=? AND status='processing' AND claimed_by=? AND lease_expires_at>?"
DELIVERY_RESCHEDULE = "UPDATE generation_ops_alert_deliveries SET status='pending',claimed_at=NULL,claimed_by=NULL,lease_expires_at=NULL,available_at=?,last_error=? WHERE delivery_id=? AND status='processing' AND claimed_by=? AND lease_expires_at>?"
